/**
 * The keyboards demo mode can stand in for: every QMK keyboard on the
 * firmware list, each as its released (multi-os) firmware builds it, so a
 * keymap laid out in the demo fits the real keyboard key for key.
 *
 * The data (boards.json, GENERATED by scripts/generateQmkDemoBoards.py) is
 * loaded only when the demo starts: it is every keyboard's vial.json and
 * default keymap, which nobody with a keyboard plugged in needs.
 */
import { QMK_FIRMWARE } from "../../lib/firmwareDownloads";

export interface DemoBoard {
  /** Display name, as the firmware list has it ("ClickBoard ErgoMini"). */
  name: string;
  /** xz-compressed vial.json, base64, as the firmware embeds it. */
  definitionXzBase64: string;
  rows: number;
  cols: number;
  /** Keycode names indexed [layer][row][col]. */
  keymap: string[][][];
  layersPerBlock: number;
  blockCount: number;
  unlockKeys: Array<{ row: number; col: number }>;
  entries: { tapDance: number; combo: number; keyOverride: number };
}

/** The keyboard the demo opens on when nothing else was chosen. */
export const DEFAULT_DEMO_BOARD = "clickboard_ergomini";

const STORAGE_KEY = "keebon.qmk.demoBoard";

/** The keyboards to offer, in the firmware list's order: id and name. */
export function demoBoardChoices(): { id: string; name: string }[] {
  return QMK_FIRMWARE.map((f) => ({ id: f.asset, name: f.name }));
}

function known(id: string | null | undefined): id is string {
  return Boolean(id) && QMK_FIRMWARE.some((f) => f.asset === id);
}

/** The keyboard picked last time in this browser, or the default. */
export function rememberedDemoBoard(): string {
  try {
    const stored = localStorage.getItem(STORAGE_KEY);
    if (known(stored)) return stored;
  } catch {
    // Storage blocked (private window, previews): the default will do.
  }
  return DEFAULT_DEMO_BOARD;
}

export function rememberDemoBoard(id: string): void {
  try {
    localStorage.setItem(STORAGE_KEY, id);
  } catch {
    // Not remembered; the demo still opens on what was picked.
  }
}

/** One keyboard's demo data (falls back to the default for an unknown id). */
export async function loadDemoBoard(
  id: string,
): Promise<{ id: string; board: DemoBoard }> {
  const all = (await import("./boards.json")).default as unknown as Record<
    string,
    DemoBoard
  >;
  const key = all[id] ? id : DEFAULT_DEMO_BOARD;
  return { id: key, board: all[key] };
}
